import java.nio.file.*;import java.util.*;import java.util.regex.*;import javax.xml.parsers.*;import org.w3c.dom.*;
public class RegexCheck {
 public static void main(String[]args)throws Exception{int n=0,errors=0;var f=DocumentBuilderFactory.newInstance();f.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd",false);var b=f.newDocumentBuilder();try(var files=Files.list(Path.of(args[0],"modes"))){for(var p:files.filter(p->p.toString().endsWith(".xml")).sorted().toList()){var doc=b.parse(p.toFile());var nodes=doc.getElementsByTagName("*");for(int i=0;i<nodes.getLength();i++){Element e=(Element)nodes.item(i);String tag=e.getTagName();String re=null;if(tag.equals("SEQ_REGEXP")||tag.equals("EOL_SPAN_REGEXP"))re=e.getTextContent();if(tag.equals("BEGIN")&&e.getParentNode().getNodeName().equals("SPAN_REGEXP"))re=e.getTextContent();if(tag.equals("END")&&e.getAttribute("REGEXP").equals("TRUE"))re=e.getTextContent().replaceAll("\\$[0-9]+","DELIM");if(e.hasAttribute("DIGIT_RE"))re=e.getAttribute("DIGIT_RE");if(tag.equals("PROPERTY")&&e.getAttribute("NAME").matches(".*(?:NextLines?|ThisLine)"))re=e.getAttribute("VALUE");if(re==null)continue;n++;try{Pattern.compile(re);}catch(PatternSyntaxException ex){System.out.println(p.getFileName()+":"+tag+": "+ex.getDescription()+" :: "+re);errors++;}}}}System.out.println("Regex patterns: "+n+", errors: "+errors);if(errors>0)System.exit(1);}
}
